#[test]
fn gain_golden_and_null() {
    let b = stereo(sine(8000, 440.0, 0.5, 0.5));
    let out = ok_t("gain", &[("by", "0.5x")], b.clone());
    for (o, i) in out.data.iter().flatten().zip(b.data.iter().flatten()) {
        assert_eq!(*o, *i * 0.5);
    }
    let out = ok_t("gain", &[("by", "-6dB")], b.clone());
    assert!((out.peak() / b.peak() - db(-6.0)).abs() < 1e-6);
    let out = ok_t("gain", &[("by", "L=-6dB,R=0dB")], b.clone());
    assert_eq!(out.data[1], b.data[1]);
    assert!((out.data[0][10] - b.data[0][10] * db(-6.0)).abs() < 1e-7);
    let out = ok_t("gain", &[("by", "2=2x")], b.clone());
    assert_eq!(out.data[0], b.data[0]);
    // mix 0% is bit-exact identity; 50% is halfway
    assert_eq!(ok_t("gain", &[("by", "-12dB"), ("mix", "0%")], b.clone()), b);
    let half = ok_t("gain", &[("by", "0x"), ("mix", "50%")], b.clone());
    assert!((half.data[0][10] - b.data[0][10] * 0.5).abs() < 1e-7);
}

#[test]
fn gain_errors_and_warnings() {
    let m = sine(8000, 440.0, 0.2, 0.5);
    assert_eq!(err_code(run_t("gain", &[("by", "R=-3dB")], m.clone()).0), 2);
    assert_eq!(err_code(run_t("gain", &[("by", "-14LUFS")], m.clone()).0), 2);
    assert_eq!(err_code(run_t("gain", &[("by", "loud")], m.clone()).0), 2);
    let (out, c) = run_t("gain", &[("by", "+12dB")], m);
    assert!(out.unwrap().peak() > 1.0);
    assert!(has_warning(&c, "clipping"));
    assert!(ok_t("gain", &[("by", "6dB")], AudioBuffer::new(8000, 1, 0)).is_empty());
}

