#[test]
fn resample_44k1_to_48k_sine() {
    let b = sine(44100, 1000.0, 1.0, 0.5);
    for to in ["48000", "48k", "48kHz"] {
        let out = ok_t("resample", &[("to", to)], b.clone());
        assert_eq!(out.sample_rate, 48000);
        assert_eq!(out.frames(), 48000);
        let r = sine(48000, 1000.0, 1.0, 0.5);
        let err = (2000..46000).map(|i| (out.data[0][i] - r.data[0][i]).abs()).fold(0.0f32, f32::max);
        assert!(err < 1e-3, "max error {err}");
    }
    let out = ok_t("resample", &[("to", "44.1kHz")], sine(48000, 440.0, 0.5, 0.5));
    assert_eq!((out.sample_rate, out.frames()), (44100, 22050));
    let same = sine(48000, 440.0, 0.1, 0.5);
    assert_eq!(ok_t("resample", &[("to", "48k")], same.clone()), same);
    assert_eq!(err_code(run_t("resample", &[("to", "12Hz")], same).0), 2);
    let fast = ok_t("resample", &[("to", "22050"), ("quality", "fast")], stereo(b));
    assert_eq!((fast.channels(), fast.frames()), (2, 22050));
}

