fn gappy(sr: u32) -> AudioBuffer {
    // 1 s tone, 1 s near-silence (noise at -60 dBFS peak), 1 s tone, 0.2 s silence, 1 s tone
    concat_bufs(&[
        sine(sr, 440.0, 1.0, 0.5),
        noise(sr, 1.0, db(-60.0), 2),
        sine(sr, 440.0, 1.0, 0.5),
        silence(sr, 0.2),
        sine(sr, 440.0, 1.0, 0.5),
    ])
}

#[test]
fn silence_detect_regions_and_markers() {
    let (r, c, dir) = run_custom("silence detect", &[("markers", "true")], &[gappy(16000)], Some("marks.csv"), |_| {});
    let v = r.unwrap();
    let regions = v["regions"].as_array().unwrap();
    assert_eq!(regions.len(), 1, "{v}");
    let start = regions[0]["start_s"].as_f64().unwrap();
    let end = regions[0]["end_s"].as_f64().unwrap();
    assert!((start - 1.0).abs() < 0.01 && (end - 2.0).abs() < 0.01, "{start}..{end}");
    // uniform noise with peak -60 dBFS has an RMS of -60 - 4.77 dB
    let floor = regions[0]["floor_db"].as_f64().unwrap();
    assert!((floor + 64.77).abs() < 0.5, "floor {floor}");
    assert_eq!(c.outputs.len(), 1);
    let csv = std::fs::read_to_string(dir.path("marks.csv")).unwrap();
    assert!(csv.starts_with("name,start_s,end_s"));
    assert_eq!(csv.lines().count(), 2);
    // shorter minimum finds the 0.2 s gap too; JSON markers
    let (r, _, dir) = run_custom(
        "silence detect",
        &[("min", "150ms"), ("markers", "true")],
        &[gappy(16000)],
        Some("marks.json"),
        |_| {},
    );
    assert_eq!(r.unwrap()["count"], 2);
    let j: Value = serde_json::from_slice(&std::fs::read(dir.path("marks.json")).unwrap()).unwrap();
    assert_eq!(j["markers"].as_array().unwrap().len(), 2);
    // no markers: nothing written
    let (r, c, _d) = run_custom("silence detect", &[], &[sine(8000, 300.0, 1.0, 0.5)], None, |_| {});
    assert_eq!(r.unwrap()["count"], 0);
    assert!(c.outputs.is_empty());
}

#[test]
fn silence_trim_edges_and_all() {
    let sr = 16000;
    let b = concat_bufs(&[silence(sr, 0.5), sine(sr, 440.0, 1.0, 0.5), silence(sr, 0.7)]);
    let out = ok_t("silence trim", &[], b.clone());
    // the tone's first sample is exactly 0, so the first audible sample is at index 1
    assert!(out.frames().abs_diff(16000 + 2 * 160) <= 2, "{}", out.frames());
    let b = concat_bufs(&[
        sine(sr, 440.0, 1.0, 0.5),
        silence(sr, 2.0),
        sine(sr, 440.0, 1.0, 0.5),
        silence(sr, 0.3),
        sine(sr, 440.0, 1.0, 0.5),
    ]);
    let (out, c) = run_t("silence trim", &[("all", "true")], b);
    let out = out.unwrap();
    // the 2 s pause becomes 0.5 s; the 0.3 s pause is untouched
    let want = 3.0 + 0.5 + 0.3;
    assert!((out.duration_s() - want).abs() < 0.02, "{}", out.duration_s());
    assert_eq!(c.metrics["pauses_shortened"], 1);
    // all-silent input is left unchanged with a warning
    let (out, c) = run_t("silence trim", &[], silence(sr, 0.5));
    assert_eq!(out.unwrap().frames(), 8000);
    assert!(has_warning(&c, "all_silent"));
}

#[test]
fn silence_pad_adds_frames() {
    let b = stereo(sine(8000, 440.0, 0.5, 0.5));
    let out = ok_t("silence pad", &[("start", "1s"), ("end", "250ms")], b.clone());
    assert_eq!(out.frames(), 8000 + 4000 + 2000);
    assert_eq!(out.slice(8000, 12000), b);
    let (out, _) = run_tc("silence pad", &[("end", "2b")], b.clone(), |c| c.globals.bpm = Some(60.0));
    assert_eq!(out.unwrap().frames(), 4000 + 16000);
    assert_eq!(ok_t("silence pad", &[], b.clone()), b);
}

