#[test]
fn mix_gains_offsets_and_length() {
    let sr = 8000;
    let a = sine(sr, 440.0, 1.0, 0.4);
    let b = sine(sr, 660.0, 0.5, 0.4);
    let (r, c, dir) = run_custom(
        "mix",
        &[("gains", "0dB,-6dB"), ("offsets", "0s,0.75s")],
        &[a.clone(), b.clone()],
        Some("m.wav"),
        |_| {},
    );
    r.unwrap();
    let out = read_wav(&dir.path("m.wav"));
    assert_eq!(out.frames(), 6000 + 4000);
    assert_eq!(out.channels(), 1);
    let g = db(-6.0);
    for i in [100usize, 5000, 7000, 9999] {
        let want = a.data[0].get(i).copied().unwrap_or(0.0) + if i >= 6000 { b.data[0][i - 6000] * g } else { 0.0 };
        assert!((out.data[0][i] - want).abs() < 1e-6, "frame {i}");
    }
    assert!(!has_warning(&c, "clipping"));
}

#[test]
fn mix_pans_constant_power() {
    let sr = 8000;
    let a = sine(sr, 440.0, 0.5, 0.5);
    let (r, c, dir) =
        run_custom("mix", &[("pans", "-100,0,+40")], &[a.clone(), a.clone(), a.clone()], Some("p.wav"), |_| {});
    r.unwrap();
    assert!(c.notes.contains_key("pan_law"));
    let out = read_wav(&dir.path("p.wav"));
    assert_eq!(out.channels(), 2);
    let (l40, r40) = crate::mix::pan_gains(40.0);
    let k = std::f32::consts::FRAC_1_SQRT_2;
    let i = 37;
    let x = a.data[0][i];
    assert!((out.data[0][i] - x * (1.0 + k + l40)).abs() < 1e-5);
    assert!((out.data[1][i] - x * (k + r40)).abs() < 1e-5);
    // hard left leaves the right channel silent; summed power is constant across positions
    let (_, _, dir) = run_custom("mix", &[("pans", "-100")], std::slice::from_ref(&a), Some("l.wav"), |_| {});
    assert!(read_wav(&dir.path("l.wav")).data[1].iter().all(|v| v.abs() < 1e-7));
    for p in [-100.0, -60.0, -20.0, 0.0, 33.0, 100.0] {
        let (l, r) = crate::mix::pan_gains(p);
        let power_db = 10.0 * ((l * l + r * r) as f64).log10();
        assert!(power_db.abs() < 0.01, "pan {p}: {power_db}");
    }
    // stereo input: balance (centre = unchanged)
    let s = stereo(a.clone());
    let (_, _, dir) = run_custom("mix", &[("pans", "0")], std::slice::from_ref(&s), Some("s.wav"), |_| {});
    let out = read_wav(&dir.path("s.wav"));
    assert!((out.data[0][i] - s.data[0][i]).abs() < 1e-6);
}

#[test]
fn mix_normalize_clipping_and_errors() {
    let a = sine(8000, 440.0, 0.5, 0.8);
    let (r, c, _d) = run_custom("mix", &[], &[a.clone(), a.clone()], Some("c.wav"), |_| {});
    r.unwrap();
    assert!(has_warning(&c, "clipping"));
    let (_, c, dir) = run_custom("mix", &[("normalize", "peak")], &[a.clone(), a.clone()], Some("n.wav"), |_| {});
    assert!(!has_warning(&c, "clipping"));
    let out = read_wav(&dir.path("n.wav"));
    assert!((lin_to_db(out.peak() as f64) + 1.0).abs() < 1e-3);
    let (r, _, _d) = run_custom("mix", &[("gains", "0dB,0dB,0dB")], &[a.clone(), a.clone()], Some("e.wav"), |_| {});
    assert_eq!(r.unwrap_err().exit_code, 2);
    let (r, _, _d) = run_custom("mix", &[("pans", "150")], std::slice::from_ref(&a), Some("e2.wav"), |_| {});
    assert_eq!(r.unwrap_err().exit_code, 2);
    // inputs at other rates are resampled to the first's
    let b = sine(16000, 440.0, 0.5, 0.2);
    let (_, _, dir) = run_custom("mix", &[], &[a, b], Some("r.wav"), |_| {});
    let out = read_wav(&dir.path("r.wav"));
    assert_eq!((out.sample_rate, out.frames()), (8000, 4000));
}

