fn png_size(path: &std::path::Path) -> (u32, u32) {
    let dec = png::Decoder::new(std::fs::File::open(path).unwrap());
    let reader = dec.read_info().unwrap();
    let info = reader.info();
    (info.width, info.height)
}

#[test]
fn waveform_formats() {
    let b = stereo(sine(8000, 50.0, 2.0, 0.6));
    let (r, _, dir) =
        run_custom("waveform", &[("width", "300"), ("height", "80")], std::slice::from_ref(&b), Some("w.png"), |_| {});
    assert_eq!(r.unwrap()["format"], "png");
    assert_eq!(png_size(&dir.path("w.png")), (300, 80));
    let (_, _, dir) = run_custom("waveform", &[("split", "true")], std::slice::from_ref(&b), Some("w.svg"), |_| {});
    let svg = std::fs::read_to_string(dir.path("w.svg")).unwrap();
    assert!(svg.starts_with("<svg") && svg.matches("<path").count() == 2);
    let (_, _, dir) =
        run_custom("waveform", &[("peaks-per-second", "10")], std::slice::from_ref(&b), Some("w.json"), |_| {});
    let j: Value = serde_json::from_slice(&std::fs::read(dir.path("w.json")).unwrap()).unwrap();
    assert_eq!(j["buckets"], 20);
    let peaks = &j["peaks"][0];
    let mx = peaks["max"][3].as_f64().unwrap();
    let mn = peaks["min"][3].as_f64().unwrap();
    assert!((mx - 0.6).abs() < 0.01 && (mn + 0.6).abs() < 0.01, "{mn} {mx}");
    // default output is PNG beside the input
    let (r, c, _d) = run_custom("waveform", &[], std::slice::from_ref(&b), None, |_| {});
    r.unwrap();
    assert!(c.outputs[0].path.ends_with("in0.waveform.png"));
    // unsupported extension
    let (r, _, _d) = run_custom("waveform", &[], &[b], Some("w.gif"), |_| {});
    assert_eq!(r.unwrap_err().exit_code, 4);
    // empty input still renders
    let (r, _, _d) = run_custom("waveform", &[], &[AudioBuffer::new(8000, 1, 0)], Some("e.png"), |_| {});
    r.unwrap();
}

#[test]
fn spectrogram_finds_the_tone() {
    let b = sine(48000, 1000.0, 1.0, 0.5);
    let (r, _, dir) = run_custom("spectrogram", &[("mel", "0")], std::slice::from_ref(&b), Some("s.json"), |_| {});
    let v = r.unwrap();
    assert_eq!(v["bins"], 1025);
    let j: Value = serde_json::from_slice(&std::fs::read(dir.path("s.json")).unwrap()).unwrap();
    let frame = j["data"][40].as_array().unwrap();
    let argmax = frame
        .iter()
        .enumerate()
        .max_by(|a, b| a.1.as_f64().unwrap().partial_cmp(&b.1.as_f64().unwrap()).unwrap())
        .unwrap()
        .0;
    let hz = j["freqs_hz"][argmax].as_f64().unwrap();
    assert!((hz - 1000.0).abs() < 30.0, "peak at {hz} Hz");
    assert_eq!(j["frames"], 1 + 48000 / 512);
    assert!(frame.iter().all(|v| v.as_f64().unwrap() >= -80.0 && v.as_f64().unwrap() <= 0.0));
    // mel image
    let (r, _, dir) = run_custom("spectrogram", &[], std::slice::from_ref(&b), Some("s.png"), |_| {});
    assert_eq!(r.unwrap()["bins"], 128);
    assert_eq!(png_size(&dir.path("s.png")), (94, 128));
    let (_, _, dir) = run_custom("spectrogram", &[("width", "200"), ("height", "64")], &[b], Some("t.png"), |_| {});
    assert_eq!(png_size(&dir.path("t.png")), (200, 64));
    // very short input: one padded frame
    let (r, _, _d) = run_custom("spectrogram", &[], &[sine(8000, 440.0, 0.01, 0.5)], Some("u.json"), |_| {});
    assert_eq!(r.unwrap()["frames"], 1);
}
